	SELECT prop.ITEMID, prop2.PROPERTYVALUE as ORDER_NO, prop.PROPERTYVALUE as TYPE, prop3.PROPERTYVALUE AS LABEL, prop4.PROPERTYVALUE AS DATASOURCE_ID, prop5.PROPERTYVALUE AS SELECT_ITEMS_REFERENCE_ID, prop6.PROPERTYVALUE as MULTI_VALUE_LIST FROM CONFIGITEM item JOIN CONFIGITEMRELATION rel1 ON item.ITEMID = rel1.PARENTITEMID JOIN CONFIGITEMRELATION rel2 ON rel1.CHILDITEMID = rel2.PARENTITEMID JOIN CONFIGITEMPROPERTY prop ON rel2.CHILDITEMID = prop.ITEMID JOIN CONFIGITEMPROPERTY prop2 ON prop2.ITEMID = prop.ITEMID JOIN CONFIGITEMPROPERTY prop3 ON prop3.ITEMID = prop.ITEMID JOIN CONFIGITEMPROPERTY prop4 ON prop4.ITEMID = prop.ITEMID JOIN CONFIGITEMPROPERTY prop5 ON prop5.ITEMID = prop.ITEMID JOIN CONFIGITEMPROPERTY prop6 ON prop6.ITEMID = prop.ITEMID WHERE item.ITEMID = '3b7fb569-fb6a-468d-b794-d68b617d44fa-I' AND rel1.RELATIONTYPE = 'Form_FormSection' AND rel2.RELATIONTYPE = 'FormSection_FormField' AND prop2.PROPERTYNAME = 'ORDER' AND prop3.PROPERTYNAME = 'LABEL' AND prop4.PROPERTYNAME = 'DATASOURCE_ID' AND prop5.PROPERTYNAME = 'SELECT_ITEMS_REFERENCE_ID' AND prop6.PROPERTYNAME = 'MULTI_VALUE_LIST' and (prop.PROPERTYNAME = 'TYPE' and prop.PROPERTYVALUE in ('CkEditor', 'SelectOption', 'TextBox', 'CheckBox', 'RadioButton'))





	SELECT  'Test Set'as  GRID_NAME,  TEST_SET_UUID,TEST_SET_ID,TEST_SET_NAME, PROCESS_UUID,PAGE_UUID, VIEW_UUID,USER_ACTION_UUID,AE_INSERT_ID,AE_UPDATE_ID,AE_INSERT_TS,AE_UPDATE_TS,AE_TRANSACTION_ID,FUNCTIONAL_AREA_UUID,TAGS_UUID FROM TEST_SET WHERE FUNCTIONAL_AREA_UUID=:APP_LOGGED_IN_FUNTIONAL_AREA_ID order by TEST_SET_ID desc;


